{
  "SelectedChoices": ["reliability_test_failover"],
  "Notes": "Failover regional ensaiado no L58 (Aurora Global, warm standby): RTO medido de 4h47 e RPO de 2.140 ms no ensaio de 07/ago/2026. Duas regioes, nao tres -- divida aceita por escrito no mesmo laboratorio, tratada aqui como risco medio com prazo de reavaliacao.",
  "IsApplicable": true
}
// Os IDs de escolha ('reliability_test_failover') sao ILUSTRATIVOS: o conjunto real
// de ChoiceId por pergunta pertence a versao do lens aplicada e se le com GetAnswer
// antes de enviar UpdateAnswer -- nunca se copia de outra pergunta ou de outro lens.
// A chamada completa tambem exige WorkloadId (32 caracteres hex) e LensAlias na URL,
// nao no corpo: PATCH /workloads/{WorkloadId}/lensReviews/{LensAlias}/answers/{QuestionId}

# iam-revisao.tf -- menor privilegio para quem conduz e quem aceita risco

# CreateWorkload cria um recurso que ainda nao existe: nao ha ARN para restringir
# a chamada a um workload especifico, porque o workload nasce DESSA chamada. E o
# mesmo raciocinio do ecr:GetAuthorizationToken no L03 -- operacao sem alvo previo
# nao aceita Resource especifico, e a AWS Service Authorization Reference confirma
# isto para wellarchitected:CreateWorkload.
data "aws_iam_policy_document" "revisor" {
  statement {
    sid       = "CriarWorkload"
    effect    = "Allow"
    actions   = ["wellarchitected:CreateWorkload", "wellarchitected:ListWorkloads"]
    resources = ["*"]
  }

  # As acoes abaixo JA aceitam Resource especifico (arn do workload), diferente
  # da criacao. Restringir aqui e o que separa "pode revisar A CADENCIA" de
  # "pode revisar QUALQUER workload da conta".
  statement {
    sid    = "OperarWorkloadDaCadencia"
    effect = "Allow"
    actions = [
      "wellarchitected:GetWorkload",
      "wellarchitected:UpdateWorkload",
      "wellarchitected:GetLensReview",
      "wellarchitected:GetAnswer",
      "wellarchitected:ListAnswers",
      "wellarchitected:UpdateAnswer",
      "wellarchitected:CreateMilestone",
      "wellarchitected:ListMilestones",
      "wellarchitected:GetMilestone",
    ]
    resources = [aws_ssm_parameter.workload_arn.value]
  }
}

# Papel separado para quem tem autoridade de aceitar um risco alto sem mitigar --
# marcar IsApplicable=false com Reason=BUSINESS_PRIORITIES ou
# ARCHITECTURE_CONSTRAINTS e uma decisao de negocio, nao uma configuracao tecnica,
# e por isso e um papel a parte do revisor comum.
data "aws_iam_policy_document" "aprovador_de_risco_aceito" {
  statement {
    sid       = "AceitarRiscoComJustificativa"
    effect    = "Allow"
    actions    = ["wellarchitected:UpdateAnswer"]
    resources  = [aws_ssm_parameter.workload_arn.value]
    condition {
      test     = "StringEquals"
      variable = "aws:PrincipalTag/papel"
      values   = ["head-de-plataforma", "cto"]
    }
  }
}

resource "aws_iam_policy" "revisor" {
  name   = "${var.projeto}-wellarchitected-revisor"
  policy = data.aws_iam_policy_document.revisor.json
}

resource "aws_iam_policy" "aprovador_de_risco_aceito" {
  name   = "${var.projeto}-wellarchitected-aprovador-risco"
  policy = data.aws_iam_policy_document.aprovador_de_risco_aceito.json
}

# O ID do workload so existe DEPOIS do CreateWorkload (chamado pelo SDK, nao pelo
# Terraform -- ver a secao seguinte). Este parametro e escrito pela task de
# revisao na primeira execucao, e as policies acima leem dele a partir da segunda.
resource "aws_ssm_parameter" "workload_arn" {
  name  = "/${var.projeto}/wellarchitected/workload-arn"
  type  = "String"
  value = "arn:aws:wellarchitected:${var.regiao}:${data.aws_caller_identity.atual.account_id}:workload/PLACEHOLDER"

  lifecycle {
    ignore_changes = [value] # a task de revisao atualiza o valor real via SDK
  }
}

data "aws_caller_identity" "atual" {}

// RegistrarWorkload.cs -- o Terraform nao tem este recurso; o SDK fala com a API

using Amazon.WellArchitected;
using Amazon.WellArchitected.Model;

var cliente = new AmazonWellArchitectedClient();

// Environment so aceita PRODUCTION ou PREPRODUCTION -- nao existe valor
// intermediario. AwsRegions OU NonAwsRegions e obrigatorio; sem nenhum dos dois
// a chamada falha com ValidationException.
var criar = new CreateWorkloadRequest
{
    WorkloadName      = "cadencia-api-pedidos",
    Description       = "API de pedidos da Cadencia -- 59 laboratorios de decisao, "
                       + "revisada pela primeira vez em 2026-Q3",
    Environment        = WorkloadEnvironment.PRODUCTION,
    Lenses             = new List<string> { "wellarchitected" }, // lens padrao da AWS
    AwsRegions         = new List<string> { "us-east-1" },
    ReviewOwner        = "plataforma@cadencia.example",
    PillarPriorities   = new List<string> { "reliability", "security" }, // ordem do plano
    ClientRequestToken = Guid.NewGuid().ToString(), // idempotencia: reenvio nao duplica
};

var workload = await cliente.CreateWorkloadAsync(criar);
Console.WriteLine($"workload criado: {workload.WorkloadId}");

// Cada resposta cita o laboratorio fonte na Notes -- e o que distingue "resposta
// escrita rapido copiando o texto do lens" de "resposta com evidencia real". As
// tres abaixo usam achado JA MEDIDO nos laboratorios anteriores, nao opiniao.
var respostas = new[]
{
    new UpdateAnswerRequest
    {
        WorkloadId = workload.WorkloadId,
        LensAlias  = "wellarchitected",
        QuestionId = "REL_02", // "Como voce projeta a resiliencia da sua carga de trabalho?"
        SelectedChoices = new List<string> { "reliability_test_failover" },
        Notes = "Failover regional ensaiado no L58 (Aurora Global, warm standby): RTO "
              + "medido de 4h47 e RPO de 2.140 ms. Duas regioes, nao tres -- divida "
              + "aceita por escrito no mesmo laboratorio.",
        IsApplicable = true,
    },
    new UpdateAnswerRequest
    {
        WorkloadId = workload.WorkloadId,
        LensAlias  = "wellarchitected",
        QuestionId = "COST_02", // "Como voce governa o uso de recursos na nuvem?"
        SelectedChoices = new List<string> { "cost_rightsizing_before_commitment" },
        Notes = "A frota de EC2 da Rotamix (L59) demonstrou o padrao que a Cadencia "
              + "segue: Compute Optimizer antes de qualquer Savings Plan. A Cadencia "
              + "ainda nao comprou compromisso -- nada para verificar ainda, risco baixo.",
        IsApplicable = true,
    },
    new UpdateAnswerRequest
    {
        WorkloadId = workload.WorkloadId,
        LensAlias  = "wellarchitected",
        QuestionId = "OPS_06", // "Como voce monitora sua carga de trabalho para atingir os resultados de negocio?"
        SelectedChoices = new List<string> { "ops_actionable_alerts" },
        Notes = "3 SLOs com burn rate multi-janela (L52) substituiram 40 alarmes que "
              + "ninguem lia. Tempo ate confirmar incidente caiu de ate 6h para 65 min "
              + "medidos no proprio laboratorio.",
        IsApplicable = true,
    },
    new UpdateAnswerRequest
    {
        WorkloadId = workload.WorkloadId,
        LensAlias  = "wellarchitected",
        QuestionId = "SUS_01", // "Qual regiao voce escolhe para os seus recursos com base nos requisitos?"
        // Nenhum SelectedChoices: nenhuma das 59 decisoes anteriores considerou este
        // criterio, entao nao ha o que marcar como praticado -- IsApplicable continua
        // true (a pergunta se aplica) e a ausencia de escolha e o proprio dado.
        Notes = "Nenhum dos 59 laboratorios anteriores escolheu regiao, tipo de "
              + "instancia ou padrao de escala por criterio de sustentabilidade. Risco "
              + "alto nao por resposta ruim -- por pergunta nunca respondida.",
        IsApplicable = true,
    },
};

foreach (var req in respostas)
    await cliente.UpdateAnswerAsync(req);

Console.WriteLine($"{respostas.Length} respostas registradas, com evidencia citada em cada Notes");

// FecharRevisao.cs -- agrega risco, monta o plano, congela o milestone

using Amazon.WellArchitected;
using Amazon.WellArchitected.Model;
using Amazon.S3;
using Amazon.S3.Model;
using System.Text.Json;

var wa = new AmazonWellArchitectedClient();
var s3 = new AmazonS3Client();

var workloadId = Environment.GetEnvironmentVariable("WORKLOAD_ID")
    ?? throw new InvalidOperationException("defina WORKLOAD_ID");

var revisao = await wa.GetLensReviewAsync(new GetLensReviewRequest
{
    WorkloadId = workloadId,
    LensAlias  = "wellarchitected",
});

// RiskCounts e um mapa por nivel de risco (HIGH, MEDIUM, NONE, NOT_APPLICABLE,
// UNANSWERED). E este numero -- nao a sensacao de "acho que esta bem" -- que
// decide o que entra primeiro no plano.
var altos  = revisao.LensReview.RiskCounts.GetValueOrDefault("HIGH", 0);
var medios = revisao.LensReview.RiskCounts.GetValueOrDefault("MEDIUM", 0);

Console.WriteLine($"risco antes do milestone: {altos} alto(s), {medios} medio(s)");

if (altos < 1)
    Console.WriteLine("AVISO: zero risco alto depois de 59 laboratorios e sinal de "
        + "revisao rasa, nao de arquitetura perfeita -- confira se todas as perguntas "
        + "foram respondidas com evidencia real antes de prosseguir.");

// O plano prioriza por pilar: cada PillarReviewSummary carrega a contagem de risco
// DAQUELE pilar, e e essa ordenacao que vira o cronograma.
var plano = revisao.LensReview.PillarReviewSummaries
    .OrderByDescending(pilar => pilar.RiskCounts.GetValueOrDefault("HIGH", 0))
    .ThenByDescending(pilar => pilar.RiskCounts.GetValueOrDefault("MEDIUM", 0))
    .Select(pilar => new
    {
        pilar.PillarId,
        pilar.PillarName,
        Altos  = pilar.RiskCounts.GetValueOrDefault("HIGH", 0),
        Medios = pilar.RiskCounts.GetValueOrDefault("MEDIUM", 0),
    })
    .ToList();

// MilestoneName precisa ser unico DENTRO do workload -- um nome repetido falha
// com ConflictException, e e por isso que o nome carrega o trimestre.
var milestone = await wa.CreateMilestoneAsync(new CreateMilestoneRequest
{
    WorkloadId          = workloadId,
    MilestoneName       = $"Revisao {DateTime.UtcNow:yyyy}-Q{(DateTime.UtcNow.Month - 1) / 3 + 1}",
    ClientRequestToken  = Guid.NewGuid().ToString(),
});

Console.WriteLine($"milestone {milestone.MilestoneNumber} salvo para o workload {workloadId}");

// O relatorio sai do console e vai para quem pediu evidencia -- sem exigir acesso
// nenhum a conta AWS da Cadencia.
var relatorio = JsonSerializer.Serialize(new { milestone.MilestoneNumber, altos, medios, plano });
await s3.PutObjectAsync(new PutObjectRequest
{
    BucketName  = Environment.GetEnvironmentVariable("BUCKET_RELATORIO"),
    Key         = $"revisoes/{DateTime.UtcNow:yyyy-MM-dd}-milestone-{milestone.MilestoneNumber}.json",
    ContentBody = relatorio,
});

# cadencia.tf -- o Terraform nao cria o workload, mas cria o que faz a
# revisao se repetir sem depender de alguem lembrar.

resource "aws_s3_bucket" "relatorios_revisao" {
  bucket = "${var.projeto}-wellarchitected-relatorios"
}

resource "aws_s3_bucket_versioning" "relatorios_revisao" {
  bucket = aws_s3_bucket.relatorios_revisao.id
  versioning_configuration { status = "Enabled" }
}

# Retencao de 3 anos: e o historico auditavel que sobrevive mesmo se alguem
# apagar o workload no console sem querer -- ver o callout de limpeza.
resource "aws_s3_bucket_lifecycle_configuration" "relatorios_revisao" {
  bucket = aws_s3_bucket.relatorios_revisao.id
  rule {
    id     = "retencao-3-anos"
    status = "Enabled"
    expiration { days = 1095 }
  }
}

resource "aws_sns_topic" "lembrete_revisao" {
  name = "${var.projeto}-wellarchitected-lembrete"
}

# O plantao do L52 e quem recebe o lembrete -- reaproveita o topico e a rotacao
# ja existentes em vez de criar um segundo caminho de notificacao paralelo.
resource "aws_sns_topic_subscription" "plantao" {
  topic_arn = aws_sns_topic.lembrete_revisao.arn
  protocol  = "email"
  endpoint  = var.email_plantao
}

# EventBridge Scheduler dispara a task ECS que roda RegistrarWorkload.cs e
# FecharRevisao.cs -- reaproveita o cluster do L01 em vez de criar computacao nova.
resource "aws_scheduler_schedule" "revisao_trimestral" {
  name                         = "${var.projeto}-wellarchitected-trimestral"
  schedule_expression          = "rate(90 days)"
  schedule_expression_timezone = "America/Sao_Paulo"

  flexible_time_window { mode = "OFF" }

  target {
    arn      = aws_ecs_cluster.principal.arn
    role_arn = aws_iam_role.scheduler_revisao.arn

    ecs_parameters {
      task_definition_arn = aws_ecs_task_definition.revisao_wa.arn
      launch_type          = "FARGATE"
      network_configuration {
        subnets         = aws_subnet.privada[*].id
        security_groups = [aws_security_group.task.id]
      }
    }

    sns_target { message_group_id = null } # nao aplicavel a FIFO; mantido por clareza
    retry_policy {
      maximum_retry_attempts       = 2
      maximum_event_age_in_seconds = 3600
    }
    dead_letter_config { arn = aws_sns_topic.lembrete_revisao.arn }
  }
}

resource "aws_iam_role" "scheduler_revisao" {
  name               = "${var.projeto}-scheduler-revisao"
  assume_role_policy = data.aws_iam_policy_document.confianca_scheduler.json
}

data "aws_iam_policy_document" "confianca_scheduler" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["scheduler.amazonaws.com"]
    }
  }
}
